  type RootRouteTree,
  type RSCSegmentData,
  type RefreshState,
  type RouteTreeAccumulator,
  convertFlightRouterStateToRouteTree,
  convertRootFlightRouterStateToRouteTree,
  createMetadataRouteTree,
  createRootRouteTree,
