node_modules/next/dist/client/components/segment-cache/scheduler.js.map:1:{"version":3,"sources":["../../../../src/client/components/segment-cache/scheduler.ts"],"sourcesContent":["import {
  compareParams,
  ParamsChange,
  getSegmentVaryPathForRequest,
  getStaticSegmentVaryPathForRequest,
} from './vary-path'
import type {
  FlightRouterState,
  CacheNode,
} from '../../../shared/lib/app-router-types'
import {
  PrefetchHint,
  StaticPrefetchDisabled,
} from '../../../shared/lib/app-router-types'
import {
  readOrCreateRouteCacheEntry,
  readRouteCacheEntry,
  readOrCreateSegmentCacheEntry,
  fetchRouteOnCacheMiss,
  fetchSegmentPrefetchesUsingStaticRequest,
  EntryStatus,
  type FulfilledRouteCacheEntry,
  type RouteCacheEntry,
  type RouteTree,
