        // rewrite that appended segments the URL doesn't have.
        const joinedRemainingParts = pathnameParts
          .slice(partIndex)
          .map(canonicalizeURLPart)
          .join('/')
        if (joinedRemainingParts !== paramCacheKey) {
          return handleMismatchDueToRewrite(
            existingEntry,
            now,
            pathname,
